export type RowKey = keyof typeof ROWS

export function rowText(key: string, lang: Lang): string | undefined {
  const row = (ROWS as Record<string, Ten>)[key]
  return row?.[ROW_LANGS.indexOf(lang as (typeof ROW_LANGS)[number])]
}
